?><!doctype html><html><head><meta charset="utf-8"><title><?php p($title.' '.($draft?'Entwurf':$i['invoice_no']));?></title></head><body><div class="doc">
<header class="doc-head"><div><?php if($logo):?><img class="doc-logo" src="<?php p($logo);?>"><?php else:?><strong><?php p($company['name']??'');?></strong><?php endif;?></div><div class="doc-company"><strong><?php p($company['name']??'');?></strong><br><?php p($company['street']??'');?><br><?php p(trim(($company['zip']??'').' '.($company['city']??'')));?><?php if(!empty($company['phone'])):?><br>Telefon: <?php p($company['phone']);?><?php endif;?><?php if(!empty($company['email'])):?><br>Mail: <?php p($company['email']);?><?php endif;?><?php if(!empty($company['website'])):?><br>Web: <?php p($company['website']);?><?php endif;?><?php foreach([1,2] as $b):if(!empty($company['bank'.$b.'_name'])):?><div class="doc-bank"><strong>Bankverbindung</strong><?php p($company['bank'.$b.'_name']);?><br>IBAN <?php p($company['bank'.$b.'_iban']??'');?><br>BIC <?php p($company['bank'.$b.'_bic']??'');?></div><?php endif;endforeach;?></div></header>
