<h1 class="doc-title"><?php p($draft?$title.' – Entwurf':$title);?></h1>
<table class="doc-table"><thead><tr><th class="p">Pos.</th><th class="q">Anzahl</th><th class="u">Einheit</th><th>Bezeichnung</th><th class="price">Einzelpreis</th><th class="total">Gesamtpreis</th></tr></thead><tbody><?php foreach($items as $n=>$x):?><tr><td><?php p($n+1);?></td><td class="q"><?php p(number_format((float)$x['quantity'],2,',','.'));?></td><td><?php p($x['unit']);?></td><td class="doc-desc"><?php if(!empty($x['is_alternative'])):?><div class="doc-alt">Alternativposition</div><?php endif;?><?php echo (string)$x['description'];?></td><td class="price"><?php p(number_format((float)$x['unit_price'],2,',','.'));?> €</td><td class="total"><?php p(number_format((float)$x['total_price'],2,',','.'));?> €</td></tr><?php endforeach;?></tbody></table>
<div class="doc-totals"><div class="doc-total-row"><span>Summe</span><strong><?php p(number_format((float)$i['net_amount'],2,',','.'));?> €</strong></div><div class="doc-total-row"><span>Mehrwertsteuer <?php p(number_format((float)$i['vat_rate'],0,',','.'));?>%</span><span><?php p(number_format((float)$i['gross_amount']-(float)$i['net_amount'],2,',','.'));?> €</span></div><div class="doc-total-row doc-total-grand"><span>Gesamtbetrag</span><span><?php p(number_format((float)$i['gross_amount'],2,',','.'));?> €</span></div><?php if($type==='final'&&(float)($i['advance_gross_amount']??0)>0):?><div class="doc-total-row"><span>abzgl. Abschläge</span><span>- <?php p(number_format((float)$i['advance_gross_amount'],2,',','.'));?> €</span></div><div class="doc-total-row doc-total-grand"><span>Verbleibender Zahlbetrag</span><span><?php p(number_format($payable,2,',','.'));?> €</span></div><?php endif;?></div>
